<?php /** The upload's preview (nothing written). Data: p, fileName, src */ ?>
<div class="card" id="upload-preview-card"><div class="card-header"><h5 class="card-title mb-0">Preview of <?= e($fileName) ?></h5><span class="fs-12 text-muted"><?= (int) $p['checks'] ?> check<?= (int) $p['checks'] === 1 ? '' : 's' ?>, <?= (int) $p['lines'] ?> line<?= (int) $p['lines'] === 1 ? '' : 's' ?> through <?= e($p['mapping_key']) ?> (<?= e($p['kind']) ?>)</span></div><div class="card-body">
<?php if ($p['missing'] !== []): ?><div class="alert alert-danger fs-12" id="upload-preview-missing">The file lacks the column<?= count($p['missing']) === 1 ? '' : 's' ?> for <?= e(implode(', ', $p['missing'])) ?> — choose another mapping, or fix the mapping.</div><?php endif; ?>
<?php if ($p['dates'] !== []): ?><h6 class="fs-12 text-muted text-uppercase">The dates it holds</h6><ul class="list-unstyled fs-12 mb-3" id="upload-preview-dates"><?php foreach ($p['dates'] as $d): ?><li id="upload-preview-date-<?= e($d['date']) ?>"><strong><?= e(format_date($d['date'])) ?></strong> — <?= (int) $d['lines'] ?> line<?= (int) $d['lines'] === 1 ? '' : 's' ?> — <?= $d['run'] === null ? 'no run yet' : 'run ' . (int) $d['run_no'] . ' ' . e($d['run']) . ' (re-run if the day changes)' ?></li><?php endforeach; ?></ul><?php endif; ?>
<?php if ($p['preview'] !== []): ?><div class="table-responsive mb-3"><table class="table table-sm fs-12 mb-0" id="upload-preview-table"><thead><tr><th>Date</th><th>Check</th><th>PLU</th><th>Item</th><th class="text-end">Qty</th><th class="text-end">Price</th><th>Flags</th><th>Modifiers</th></tr></thead><tbody>
<?php foreach ($p['preview'] as $r): ?><tr><td><?= e($r['business_date']) ?></td><td><?= e($r['external_id']) ?></td><td><?= e($r['plu']) ?></td><td><?= e((string) $r['name']) ?></td><td class="text-end"><?= e(fmt_num($r['qty'], 2)) ?></td><td class="text-end"><?= $r['unit_price'] === null ? '' : e(ri_money($r['unit_price'])) ?></td><td><?= $r['voided'] ? '<span class="badge bg-soft-danger text-danger">void</span>' : '' ?><?= $r['comp'] ? '<span class="badge bg-soft-warning text-warning">comp</span>' : '' ?></td><td><?= e(implode(', ', $r['modifiers'])) ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?>
<?php if ($p['unknown_plus'] !== []): ?><h6 class="fs-12 text-muted text-uppercase">New PLUs it will create (unmapped — to map)</h6><ul class="fs-12 mb-3" id="upload-preview-unknown"><?php foreach ($p['unknown_plus'] as $u): ?><li><?= e($u['plu']) ?> — <?= e($u['name']) ?></li><?php endforeach; ?></ul><?php endif; ?>
<?php if ($p['bad'] !== []): ?><h6 class="fs-12 text-danger text-uppercase">Rows it cannot read (<?= (int) $p['bad_count'] ?>)</h6><ul class="fs-12 text-danger mb-0" id="upload-preview-bad"><?php foreach ($p['bad'] as $b): ?><li>Row <?= (int) $b['row'] ?>: <?= e($b['reason']) ?></li><?php endforeach; ?></ul><?php endif; ?>
</div></div>
